                                                        <span style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }} style={{ fontSize: "0.75rem" }}>Livello raggiunto</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <span style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }} style={{ transition: "transform 300ms" }}>arrow_forward</span>
                                        </div>
                                    )
                                })}
                    </M3DialogContent>
                    <M3DialogActions>
                        <M3Button onClick={() => setViewingStudents(null)} variant="text">Chiudi</M3Button>
                    </M3DialogActions>
                </M3Dialog>
            )}
        </div>
    );
};

