}

interface StudentDashboardItemProps {
    student: Studente;
    evaluations: Valutazione[];
    onClick: (student: Studente) => void;
}

const StudentDashboardItem = React.memo(({ student, evaluations, onClick }: StudentDashboardItemProps) => {
    const { trend } = calculatePerformance(student.id, 'Complessivo', evaluations);
    const trendClass = trend === 'up' ? 'class-dashboard-trend-up' : trend === 'down' ? 'class-dashboard-trend-down' : 'class-dashboard-trend-neutral';
    const trendIcon = trend === 'up' ? 'trending_up' : trend === 'down' ? 'trending_down' : 'trending_flat';

    return (
        <button 
            onClick={() => onClick(student)}
            
        >
            <Avatar name={`${student.nome} ${student.cognome}`} size="md" />
            <div style={{ flexGrow: "1", minWidth: "0" }}>
                <p >{student.cognome} {student.nome}</p>
                <div >
                    <span className={`material-symbols-outlined class-dashboard-trend-icon ${trendClass}`}>{trendIcon}</span>
                    <span className={`class-dashboard-trend-label ${trendClass}`}>
                        {trend === 'up' ? 'In crescita' : trend === 'down' ? 'In calo' : 'Stabile'}
                    </span>
                </div>
            </div>
            <span >chevron_right</span>
        </button>
    );
});

const ClassDashboard: React.FC<ClassDashboardProps> = ({
    selectedClass,
    onNavigate,
    onStartImpromptuSession,
    onStartPlannedLesson,
    onViewStudentProfile,
}) => {
  const { layers } = useTheme();
    const students = useStudentStore(state => state.students);
    const evaluations = useStudentStore(state => state.evaluations);
    const slots = useAcademicStore(state => state.slots);
    const lessons = useAcademicStore(state => state.lessons);
    const submissions = useAcademicStore(state => state.submissions) || [];

    const filteredStudents = useMemo(() => {
        return students.filter(s => s.classe === selectedClass).sort((a, b) => a.cognome.localeCompare(b.cognome));
    }, [students, selectedClass]);

    const todaysLesson = useMemo(() => {
        const todayName = DAYS_OF_WEEK[new Date().getDay() - 1] || DAYS_OF_WEEK[6];
        const lessonsToday = Object.values(slots)
            .filter((slot: Slot) => slot.giorno === todayName && slot.classe === selectedClass && slot.lezioneId && lessons[slot.lezioneId])
            .map((slot: Slot) => ({ slot, lesson: lessons[slot.lezioneId!] }))
            .filter(item => item.lesson && !item.lesson.svolta)
            .sort((a, b) => a.slot.ora.localeCompare(b.slot.ora));

        return lessonsToday.length > 0 ? lessonsToday[0] : null;
    }, [slots, lessons, selectedClass]);

    // Count pending submissions for this class
    const inboxCount = useMemo(() => {
        return submissions.filter(s => s.status === 'pending' && filteredStudents.some(st => st.id === s.studentId)).length;
    }, [submissions, filteredStudents]);

    return (
        <div >
            <SectionHeader 
                title={`Cruscotto Classe ${selectedClass}`}
                subtitle="Gestione didattica, valutazioni e monitoraggio in tempo reale"
                 style={{ textAlign: "center" }}
            />

            <div >
                {/* Main Column */}
                <div >

                    {/* Hero Section: Lesson or Action */}
                    <section>
                        {todaysLesson ? (
                            <M3Card >
                                <div >
                                    <div >
                                        <div >
                                            <span >school</span>
                                        </div>
                                        <div style={{ flexGrow: "1", minWidth: "0" }}>
                                            <p >Prossima Lezione • {todaysLesson.slot.ora}</p>
                                            <h2 >{todaysLesson.lesson.materia}</h2>
                                            <p >{todaysLesson.lesson.contenuto}</p>
                                        </div>
                                    </div>
                                    <M3Button
                                        onClick={() => onStartPlannedLesson(todaysLesson.lesson.classe, todaysLesson.lesson.materia, `${todaysLesson.slot.giorno}-${todaysLesson.slot.ora}`, todaysLesson.lesson)}
                                        variant="primary"
                                        
                                    >
                                        <span >door_open</span>
                                        Avvia Aula Digitale
                                    </M3Button>
                                </div>
                            </M3Card>
                        ) : (
                            <M3Card >
                                <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['6'], marginBottom: layers.ref.spacing['6']}}>
                                    <div style={{ borderRadius: ref.shape[], backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]est, color: sys.colors.[var(--md-sys-color-on-surface)]-variant, width: ref.spacing[64], height: ref.spacing[64], display: "flex", alignItems: "center", justifyContent: "center" }}>
                                        <span >event_busy</span>
                                    </div>
                                    <div>
                                        <h2 style={{ color: sys.colors.[var(--md-sys-color-on-surface)], fontSize: "1.25rem", fontWeight: "bold" }}>Nessuna lezione programmata</h2>
                                        <p style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }}>Puoi avviare una lezione libera o un'attività improvvisata.</p>
                                    </div>
                                </div>
                                <M3Button onClick={() => onStartImpromptuSession(selectedClass)} variant="secondary" style={{ width: "100%" }}>
                                    <span >add_circle</span>
                                    Avvia Lezione Improvvisata
                                </M3Button>
                            </M3Card>
                        )}
                    </section>

                    {/* INBOX WIDGET */}
                    {inboxCount > 0 && (
                        <section >
                            <M3Card 
                                
                                onClick={() => onNavigate('teacher-inbox')}
                            >
                                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>mail</span>
                                            <span >
                                                {inboxCount}
                                            </span>
                                        </div>
                                        <div>
                                            <h3 style={{ color: sys.colors.on-tertiary-container, fontWeight: "bold" }}>Inbox Compiti</h3>
                                            <p style={{ color: sys.colors.on-tertiary-container/70, fontSize: "0.875rem" }}>{inboxCount} elaborati consegnati da valutare.</p>
                                        </div>
                                    </div>
                                    <div >
                                        <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>arrow_forward</span>
                                    </div>
                                </div>
                            </M3Card>
                        </section>
                    )}

                    {/* TOOLS GRID */}
                    <div >
                        {/* 1. SEZIONE REGISTRO & DIDATTICA */}
                        <section>
                            <div >
                                <span  style={{color: "layers.sys.colors.primary"}}>auto_stories</span>
                                <h3 >Registro & Didattica</h3>
                            </div>
                            <div >
                                <M3Card 
                                    
                                    onClick={() => onNavigate('register', selectedClass)}
                                >
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>book</span>
                                        </div>
                                        <div>
                                            <h4 >Diario di Bordo</h4>
                                            <p >Lezioni, assenze, note</p>
                                        </div>
                                    </div>
                                </M3Card>
                                <M3Card 
                                    
                                    onClick={() => onNavigate('didattica-inclusiva', selectedClass)}
                                >
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>accessibility_new</span>
                                        </div>
                                        <div>
                                            <h4 >Inclusione</h4>
                                            <p >PDP, PEI e strategie</p>
                                        </div>
                                    </div>
                                </M3Card>
                            </div>
                        </section>

                        {/* 2. SEZIONE VALUTAZIONE & COMPETENZE */}
                        <section>
                            <div >
                                <span  style={{color: "layers.sys.colors.secondary"}}>grading</span>
                                <h3 >Valutazione & Competenze</h3>
                            </div>
                            <div >
                                <M3Card 
                                    
                                    onClick={() => onNavigate('evaluations', selectedClass)}
                                >
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>ballot</span>
                                        </div>
                                        <div>
                                            <h4 >Voti</h4>
                                            <p >Registro valutazioni</p>
                                        </div>
                                    </div>
                                </M3Card>
                                <M3Card 
                                    
                                    onClick={() => onNavigate('class-competency-dashboard', selectedClass)}
                                >
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>psychology</span>
                                        </div>
                                        <div>
                                            <h4 >Competenze</h4>
                                            <p >Livelli e matrici</p>
                                        </div>
                                    </div>
                                </M3Card>
                            </div>
                        </section>

                        {/* 3. SEZIONE ANALISI & REPORT */}
                        <section>
                            <div >
                                <span style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }}>analytics</span>
                                <h3 >Analisi & Report</h3>
                            </div>
                            <div >
                                <M3Card 
                                    
                                    onClick={() => onNavigate('improvement-guide', selectedClass)}
                                >
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>query_stats</span>
                                        </div>
                                        <div>
                                            <h4 >Analisi AI</h4>
                                            <p >Report pedagogico</p>
                                        </div>
                                    </div>
                                </M3Card>
                                <M3Card 
                                    
                                    onClick={() => onNavigate('consiglio-di-classe', selectedClass)}
                                >
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>gavel</span>
                                        </div>
                                        <div>
                                            <h4 >Consiglio</h4>
                                            <p >Scrutini e tabelloni</p>
                                        </div>
                                    </div>
                                </M3Card>
                                <M3Card 
                                    
                                    onClick={() => onNavigate('studenti', selectedClass)}
                                >
                                    <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                        <div >
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>groups</span>
                                        </div>
                                        <div>
                                            <h4 >Anagrafica</h4>
                                            <p >Elenco studenti</p>
                                        </div>
                                    </div>
                                </M3Card>
                            </div>
                        </section>
                    </div>
                </div>

                {/* Side Column: Students List */}
                <div >
                    <M3Card variant="elevated" >
                        <div >
                            <div >
                                <h2 >Studenti</h2>
                                <span >
                                    {filteredStudents.length}
                                </span>
                            </div>

                            <div >
                                {filteredStudents.length > 0 ? filteredStudents.map(student => (
                                    <StudentDashboardItem
                                        key={student.id}
                                        student={student}
                                        evaluations={evaluations}
                                        onClick={onViewStudentProfile}
                                    />
                                )) : (
                                    <div >
                                        <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>person_off</span>
                                        <p style={{ fontSize: "0.875rem" }}>Nessuno studente in elenco.</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </M3Card>
                </div>
            </div>
        </div>
    );
};

export default React.memo(ClassDashboard);

// LEGACY - MD3 Non-compliant

import React, { useState, useMemo } from 'react';
import { 
    Studente, 
    Uda, 
    TimetableSettings, 
    AiSettings, 
    Report, 
    EventoCalendario, 
    Lezione, 
    KnowledgeBaseEntry, 
    PianoInclusione 
} from '../types';
import { 
    generateClassPlanningDocument, 
    generateSituazionePartenza, 
    suggestAnnualPlan, 
    generateMethodologyStrategies 
} from '../services/aiService';
import { generateHtmlDocxBlob, saveAs } from '../utils/documentUtils';
import { 
    M3Dialog, 
    M3DialogContent, 
    M3DialogActions, 
    M3Button, 
    InfoCard, 
    SectionHeader,
    AiThinkingGem 
} from './ui';
import { useUIStore } from '../stores/useUIStore';
import { useTheme } from '../theme/theme';

interface AnnualPlanningWizardProps {
    onClose: () => void;
    userClasses: string[];
    settings: TimetableSettings;
    aiSettings: AiSettings;
    onSaveUda: (uda: Uda) => void;
    onAddLessons: (lessons: Lezione[]) => void;
    onSaveReport: (report: Report) => void;
    onSaveEvent: (event: EventoCalendario) => void;
    knowledgeBase: KnowledgeBaseEntry[];
    students: Studente[];
    pianiInclusione: Record<string, PianoInclusione>;
}

type WizardStep = 'context' | 'situation' | 'methodology' | 'sequence' | 'preview' | 'document';

const AnnualPlanningWizard: React.FC<AnnualPlanningWizardProps> = ({
    onClose, userClasses, settings, aiSettings, onSaveUda, onAddLessons, onSaveReport, onSaveEvent, knowledgeBase, students, pianiInclusione
}) => {
  const { layers } = useTheme();
    const [step, setStep] = useState<WizardStep>('context');
    
    // UI Store for toast notifications
    const { showToast } = useUIStore(state => ({ showToast: state.actions.showToast }));
    
    // Step 1: Context
    const [selectedClass, setSelectedClass] = useState<string>(userClasses[0] || '');
    const [selectedSubject, setSelectedSubject] = useState<string>(settings.disciplines[0] || '');
    const [selectedKbFiles, setSelectedKbFiles] = useState<string[]>([]);
    
    // Step 2: Situation (AI Assisted)
    const [situationTags, setSituationTags] = useState<string[]>([]);
    const [situationNotes, setSituationNotes] = useState('');
    const [situationText, setSituationText] = useState('');
    const [isGeneratingSituation, setIsGeneratingSituation] = useState(false);

    // Step 3: Methodology & Goals
    const [methodology, setMethodology] = useState('Lezione frontale partecipata, Cooperative Learning, Laboratorio.');
    const [isGeneratingMethodology, setIsGeneratingMethodology] = useState(false);

    // Step 4: UDA Sequence
    interface PlannedUda {
        id: string;
        title: string;
        hours: number;
        topic: string;
    }
    const [plannedUdas, setPlannedUdas] = useState<PlannedUda[]>([]);
    const [newUdaTitle, setNewUdaTitle] = useState('');
    const [newUdaHours, setNewUdaHours] = useState(10);
    const [hoursPerWeek, setHoursPerWeek] = useState(3);
    const [isGeneratingPlan, setIsGeneratingPlan] = useState(false);
    const [showSequenceHelp, setShowSequenceHelp] = useState(false); // NEW: Context Help State

    // Step 5: Milestones
    const currentYear = new Date().getMonth() >= 8 ? new Date().getFullYear() : new Date().getFullYear() - 1;
    const [term1End, setTerm1End] = useState<string>(`${currentYear}-12-22`);
    const [term2End, setTerm2End] = useState<string>(`${currentYear + 1}-06-08`);
    
    // Step 6: Preview
    const [schedulePreview, setSchedulePreview] = useState<{ uda: PlannedUda, start: string, end: string }[]>([]);
    
    // General
    const [isProcessing, setIsProcessing] = useState(false);

    // --- HELPERS ---
    const recommendedFiles = useMemo(() => knowledgeBase.filter(kb => 
        kb.fileName.toLowerCase().includes('programmazione') || 
        kb.fileName.toLowerCase().includes('ptof') ||
        kb.fileName.toLowerCase().includes('curricol') ||
        kb.category === 'programmazione' || 
        kb.category === 'normativa'
    ), [knowledgeBase]);

    const toggleKbFile = (id: string) => {
        setSelectedKbFiles(prev => prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]);
    };

    const SITUATION_TAGS = [
        "Numerosa", "Poca partecipazione", "Vivace", "Livello Eterogeneo", 
        "Buona preparazione base", "Lacune diffuse", "Presenza BES/DSA", 
        "Studenti Stranieri (NAI)", "Collaborativa", "Difficoltà relazionali"
    ];

    // --- LOGIC ---

    const handleGenerateSituation = async () => {
        setIsGeneratingSituation(true);
        try {
            const text = await generateSituazionePartenza(aiSettings, {
                classe: selectedClass,
                tags: situationTags,
                notes: situationNotes
            });
            setSituationText(text);
        } catch (e) {
            console.error("Errore generazione testo situazione:", e);
            showToast("Errore durante la generazione del testo della situazione di partenza. Riprova.", "error");
        } finally {
            setIsGeneratingSituation(false);
        }
    };

    const handleGenerateMethodology = async () => {
        setIsGeneratingMethodology(true);
        try {
            const text = await generateMethodologyStrategies(aiSettings, situationText || "Classe standard");
            setMethodology(text);
        } catch (e) {
            console.error("Errore generazione metodologia:", e);
            showToast("Errore durante la generazione delle strategie metodologiche. Riprova.", "error");
        } finally {
            setIsGeneratingMethodology(false);
        }
    };

    const handleGeneratePlanFromKb = async () => {
        const kbContent = knowledgeBase
            .filter(kb => selectedKbFiles.includes(kb.id))
            .map(kb => kb.content)
            .join('\n\n');
        
        if (!kbContent) {
            showToast("Seleziona almeno un documento dalla Knowledge Base (Step 1) per generare il piano.", "info");
            return;
        }

        setIsGeneratingPlan(true);
        try {
            const plan = await suggestAnnualPlan(aiSettings, kbContent, selectedSubject, selectedClass);
            if (plan.length > 0) {
                setPlannedUdas(plan.map((u, i) => ({...u, id: `plan-gen-${i}`})));
            } else {
                showToast("L'AI non ha trovato UDA nel documento. Puoi inserirle manualmente.", "info");
            }
        } catch (e) {
            console.error("Errore durante l'analisi del documento:", e);
            showToast("Errore durante l'analisi del documento. Riprova.", "error");
        } finally {
            setIsGeneratingPlan(false);
        }
    };

    const addUdaToPlan = () => {
        if (!newUdaTitle.trim()) return;
        const newId = `temp-${Date.now()}`;
        setPlannedUdas([...plannedUdas, { id: newId, title: newUdaTitle, hours: newUdaHours, topic: newUdaTitle }]);
        setNewUdaTitle('');
        setNewUdaHours(10);
    };

    const updateUdaHours = (id: string, hours: number) => {
        setPlannedUdas(prev => prev.map(u => u.id === id ? { ...u, hours } : u));
    };

    const removeUdaFromPlan = (index: number) => {
        const list = [...plannedUdas];
        list.splice(index, 1);
        setPlannedUdas(list);
    };

    const calculateSchedule = () => {
        // Start around mid-September
        const currentDate = new Date(`${currentYear}-09-12`); 
        
        const schedule = plannedUdas.map(pUda => {
            const safeHoursPerWeek = Math.max(1, hoursPerWeek);
            const weeksNeeded = Math.ceil(pUda.hours / safeHoursPerWeek);
            
            const startDate = new Date(currentDate);
            currentDate.setDate(currentDate.getDate() + (weeksNeeded * 7));
            
            // Break for Christmas
            if (startDate.getMonth() < 11 && currentDate.getMonth() === 0) {
                currentDate.setDate(currentDate.getDate() + 14);
            }

            return {
                uda: pUda,
                start: startDate.toISOString().split('T')[0],
                end: currentDate.toISOString().split('T')[0]
            };
        });
        
        setSchedulePreview(schedule);
        setStep('preview');
    };

    const handleFinalize = async () => {
        setIsProcessing(true);
        try {
            for (const item of schedulePreview) {
                const newUda: Uda = {
                    id: `uda-gen-${Date.now()}-${Math.random()}`,
                    title: item.uda.title,
                    classe: selectedClass,
                    materia: selectedSubject,
                    introduction: `Unità di apprendimento su: ${item.uda.topic}`,
                    finalProduct: 'Verifica sommativa o elaborato',
                    competencyIds: [], 
                    phases: [
                        { id: 'ph1', title: 'Fase 1: Attivazione', description: 'Introduzione', activities: 'Lezione partecipata', duration: '2' },
                        { id: 'ph2', title: 'Fase 2: Svolgimento', description: 'Approfondimento', activities: 'Lezione ed esercizi', duration: (Math.max(1, item.uda.hours - 4)).toString() },
                        { id: 'ph3', title: 'Fase 3: Verifica', description: 'Valutazione', activities: 'Prova', duration: '2' }
                    ],
                    evaluation: 'Griglia di valutazione disciplinare',
                    tools: 'Libro di testo, LIM',
                    startDate: item.start,
                    endDate: item.end
                };
                onSaveUda(newUda);

                // Placeholder lessons
                const numLessons = Math.ceil(item.uda.hours / 1.5);
                const newLessons: Lezione[] = [];
                for(let i=0; i<numLessons; i++) {
                    newLessons.push({
                        id: `les-gen-${newUda.id}-${i}`,
                        classe: selectedClass,
                        materia: selectedSubject,
                        contenuto: `${item.uda.title} - Lezione ${i+1}`,
                        unitaDiApprendimento: newUda.title,
                        svolta: false
                    });
                }
                onAddLessons(newLessons);
            }

            onSaveEvent({ id: `evt-term1-${Date.now()}`, titolo: 'Fine 1° Periodo', data: term1End, tipo: 'scadenza', descrizione: 'Termine inserimento voti.' });
            onSaveEvent({ id: `evt-term2-${Date.now()}`, titolo: 'Termine Lezioni', data: term2End, tipo: 'scadenza', descrizione: 'Ultimo giorno di scuola.' });

            setStep('document');
        } catch (error) {
            console.error("Errore nel salvataggio dei dati:", error);
            showToast("Errore nel salvataggio dei dati. Riprova.", "error");
        } finally {
            setIsProcessing(false);
        }
    };

    const handleGenerateDoc = async () => {
        setIsProcessing(true);
        try {
            const udaList = schedulePreview.map(s => 
                `• ${s.uda.title} (${s.uda.hours}h): dal ${new Date(s.start).toLocaleDateString()} al ${new Date(s.end).toLocaleDateString()}`
            ).join('\n');

            const kbContext = knowledgeBase
                .filter(kb => selectedKbFiles.includes(kb.id))
                .map(kb => `--- DOC: ${kb.fileName} ---\n${kb.content.substring(0, 5000)}`)
                .join('\n\n');

            const studentsInClass = students.filter(s => s.classe === selectedClass);
            const besCount = studentsInClass.filter(s => !!pianiInclusione[s.id]).length;
            const stats = `Classe composta da ${studentsInClass.length} studenti.`;
            const inclStats = `Sono presenti ${besCount} studenti con Piano di Inclusione (BES/DSA).`;

            const htmlContent = await generateClassPlanningDocument(aiSettings, {
                classe: selectedClass,
                materia: selectedSubject,
                docente: settings.nomeInsegnante,
                annoScolastico: settings.annoScolasticoCorrente,
                studentiStats: stats,
                inclusioneStats: inclStats,
                udaList: udaList,
                kbContext: kbContext,
                metodologie: methodology,
                situazionePartenza: situationText
            });

            const blob = await generateHtmlDocxBlob(htmlContent, `Programmazione ${selectedClass}`);
            const fileName = `Programmazione_${selectedClass}_${selectedSubject}.docx`;
            
            const newReport: Report = {
                id: `rep-prog-${Date.now()}`,
                nome: `Programmazione Annuale ${selectedClass}`,
                dataCreazione: new Date().toISOString(),
                contesto: { tipo: 'classe', id: selectedClass, titolo: selectedClass },
                modelloUsato: { nome: 'Programmazione Annuale (Wizard)', tipo: 'docx' },
                file: { name: fileName, content: "", mimeType: 'application/msword' }
            };
            onSaveReport(newReport);
            saveAs(blob, fileName);
            
            onClose();
        } catch (e: unknown) {
            console.error("Errore generazione documento:", e);
            showToast("Errore durante la generazione del documento. Riprova.", "error");
        } finally {
            setIsProcessing(false);
        }
    };

    const renderStepIndicator = () => (
        <div >
            {['Contesto', 'Analisi', 'Metodi', 'Piano', 'Anteprima', 'Output'].map((label, idx) => {
                const stepIds: WizardStep[] = ['context', 'situation', 'methodology', 'sequence', 'preview', 'document'];
                const isActive = stepIds.indexOf(step) === idx;
                const isDone = stepIds.indexOf(step) > idx;
                
                let circleClass = 'wizard-step-circle';
                if (isActive) circleClass += ' active';
                else if (isDone) circleClass += ' completed';

                return (
                    <div key={label} >
                        <div className={circleClass}>{idx + 1}</div>
                        {idx < 5 && <div className={`wizard-step-line ${isDone ? 'completed' : ''}`}></div>}
                    </div>
                );
            })}
        </div>
    );

    return (
        <M3Dialog
            onClose={onClose}
            title="Progettazione Annuale Guidata"
            mode="fullscreen"
            level={1}
        >
            <M3DialogContent style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-low)]/30, padding: ref.spacing[0] }}>
                <div  style={{marginLeft: "auto", marginRight: "auto", width: "100%", paddingLeft: layers.ref.spacing['4'], paddingRight: layers.ref.spacing['4']}}>
                    {renderStepIndicator()}

                    {step === 'context' && (
                        <div  style={{gap: layers.ref.spacing['6']}}>
                            <SectionHeader 
                                title="1. Definisci il Contesto" 
                                subtitle="Seleziona la classe e i documenti di riferimento per iniziare la progettazione."
                                icon="settings_input_component"
                            />
                            
                            <InfoCard style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/40 }}>
                                <div >
                                    <div>
                                        <label >Classe Target</label>
                                        <select value={selectedClass} onChange={e => setSelectedClass(e.target.value)}  style={{ width: "100%" }} title="Seleziona la classe per la programmazione">
                                            {userClasses.map(c => <option key={c} value={c}>{c}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label >Materia</label>
                                        <select value={selectedSubject} onChange={e => setSelectedSubject(e.target.value)}  style={{ width: "100%" }} title="Seleziona la materia">
                                            {settings.disciplines.map(d => <option key={d} value={d}>{d}</option>)}
                                        </select>
                                    </div>
                                </div>
                            </InfoCard>

                            <InfoCard 
                                title="Documenti di Riferimento (KB)" 
                                icon="folder_open"
                                style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/40 }}
                            >
                                <div  style={{ maxHeight: ref.spacing[180] }}>
                                    {recommendedFiles.length > 0 ? recommendedFiles.map(kb => (
                                        <div key={kb.id} >
                                            <input type="checkbox" id={`kb-annual-${kb.id}`} checked={selectedKbFiles.includes(kb.id)} onChange={() => toggleKbFile(kb.id)} />
                                            <label htmlFor={`kb-annual-${kb.id}`}  style={{ width: "100%", justifyContent: "flex-start" }} title={kb.fileName}>
                                                {selectedKbFiles.includes(kb.id) && <span >check</span>}
                                                <span style={{ color: sys.colors.[var(--md-sys-typescale-body-medium)] }} style={{color: "layers.sys.colors.primary", marginRight: "0.5rem"}}>description</span>
                                                <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{kb.fileName}</span>
                                            </label>
                                        </div>
                                    )) : (
                                        <p style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }} style={{textAlign: "center", padding: layers.ref.spacing['8']}}>Nessun documento suggerito. Caricali nella KB con tag "Programmazione".</p>
                                    )}
                                </div>
                            </InfoCard>
                        </div>
                    )}

                    {step === 'situation' && (
                        <div  style={{gap: layers.ref.spacing['6']}}>
                            <SectionHeader 
                                title="2. Analisi della Classe" 
                                subtitle="Descrivi il clima della classe e il livello di partenza degli studenti."
                                icon="analytics"
                            />
                            
                            <InfoCard style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/40 }}>
                                <div  style={{marginBottom: layers.ref.spacing['8']}}>
                                    {SITUATION_TAGS.map(tag => (
                                        <button 
                                            key={tag}
                                            onClick={() => setSituationTags(p => p.includes(tag) ? p.filter(t => t !== tag) : [...p, tag])}
                                            className={`wizard-tag ${situationTags.includes(tag) ? 'active' : ''}`}
                                            title={`Aggiungi tag: ${tag}`}
                                        >
                                            {tag}
                                        </button>
                                    ))}
                                </div>
                                <div style={{marginBottom: layers.ref.spacing['8']}}>
                                    <label >Note Aggiuntive</label>
                                    <textarea  style={{ width: "100%" }} rows={2} value={situationNotes} onChange={e => setSituationNotes(e.target.value)} placeholder="Dettagli specifici sulla classe..." />
                                </div>
                                <M3Button onClick={handleGenerateSituation} disabled={isGeneratingSituation} variant="tonal" style={{width: "100%", display: "flex", justifyContent: "center", gap: layers.ref.spacing['8']}} title="Usa l'AI per scrivere l'analisi">
                                    {isGeneratingSituation ? <AiThinkingGem size="small" inline text="Analisi..." /> : 'Genera Analisi con AI'}
                                </M3Button>
                            </InfoCard>

                            {situationText && (
                                <InfoCard title="Testo Analisi" icon="description" style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/40 }}>
                                    <textarea  style={{ width: "100%" }} rows={6} value={situationText} onChange={e => setSituationText(e.target.value)} />
                                </InfoCard>
                            )}
                        </div>
                    )}

                    {step === 'methodology' && (
                        <div  style={{gap: layers.ref.spacing['6']}}>
                            <SectionHeader 
                                title="3. Obiettivi e Metodologie" 
                                subtitle="Definisci le strategie didattiche e gli strumenti che utilizzerai."
                                icon="psychology"
                            />
                            
                            <InfoCard style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/40 }}>
                                <div style={{display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: layers.ref.spacing['8']}}>
                                    <label >Strategie Didattiche</label>
                                    <M3Button onClick={handleGenerateMethodology} disabled={isGeneratingMethodology} variant="text"  style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}} title="Suggerisci metodologie adatte al contesto">
                                        {isGeneratingMethodology ? <AiThinkingGem size="small" inline /> : <><span style={{ color: sys.colors.[var(--md-sys-typescale-body-medium)] }}>lightbulb</span> Suggerisci</>}
                                    </M3Button>
                                </div>
                                <textarea  style={{ width: "100%" }} rows={8} value={methodology} onChange={e => setMethodology(e.target.value)} />
                            </InfoCard>
                        </div>
                    )}

                    {step === 'sequence' && (
                        <div  style={{gap: layers.ref.spacing['4']}}>
                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                <SectionHeader 
                                    title="4. Piano Annuale UDA" 
                                    subtitle="Organizza le unità di apprendimento in sequenza temporale."
                                    icon="view_timeline"
                                />
                                <div style={{display: "flex", gap: layers.ref.spacing['8']}}>
                                    <div style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/50, borderRadius: ref.shape[] }} style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8'], border: "1px solid layers.sys.colors.outline"}}>
                                        <span >Ore/Sett:</span>
                                        <input type="number" value={hoursPerWeek} onChange={e => setHoursPerWeek(Math.max(1, parseInt(e.target.value)))}  style={{width: "2.5rem", backgroundColor: "transparent", textAlign: "center", fontWeight: "bold", borderBottom: "1px solid layers.sys.colors.outline"}} title="Ore settimanali di lezione" />
                                    </div>
                                    <M3Button onClick={handleGeneratePlanFromKb} disabled={isGeneratingPlan || selectedKbFiles.length === 0} variant="tonal" style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}} title="Genera lista UDA dai documenti KB">
                                        {isGeneratingPlan ? <AiThinkingGem size="small" inline text="Leggo..." /> : 'Genera da KB'}
                                    </M3Button>
                                </div>
                            </div>

                            {showSequenceHelp && (
                                <InfoCard 
                                    title="Organizzazione Moduli"
                                    description="Definisci le Unità di Apprendimento (UDA) in ordine cronologico. L'app calcolerà automaticamente le date sul calendario in base al monte ore di ciascuna UDA."
                                    variant="secondary"
                                    icon="info"
                                    onClose={() => setShowSequenceHelp(false)}
                                    style={{marginBottom: layers.ref.spacing['8']}}
                                />
                            )}

                            <InfoCard style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/40 }}>
                                <div style={{display: "flex", gap: layers.ref.spacing['8'], alignItems: "flex-end"}}>
                                    <div style={{ flexGrow: "1" }}>
                                        <label >Titolo UDA</label>
                                        <input type="text" value={newUdaTitle} onChange={e => setNewUdaTitle(e.target.value)}  style={{ width: "100%" }} onKeyDown={e => e.key === 'Enter' && addUdaToPlan()} placeholder="Es. Il Verismo" />
                                    </div>
                                    <div style={{ width: ref.spacing[96] }}>
                                        <label >Ore</label>
                                        <input type="number" value={newUdaHours} onChange={e => setNewUdaHours(parseInt(e.target.value))}  style={{ width: "100%" }} />
                                    </div>
                                    <M3Button onClick={addUdaToPlan} variant="filled" style={{marginBottom: layers.ref.spacing['4']}} title="Aggiungi alla lista">Aggiungi</M3Button>
                                </div>
                            </InfoCard>

                            {isGeneratingPlan ? (
                                <div style={{ padding: ref.spacing[12] }} style={{ display: "flex", justifyContent: "center" }}>
                                    <AiThinkingGem size="large" text="Generazione piano annuale..." />
                                </div>
                            ) : (
                                <div  style={{gap: layers.ref.spacing['3'], overflowY: "auto"}}>
                                    {plannedUdas.map((uda, idx) => (
                                        <div key={uda.id} style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/30, borderRadius: ref.shape[] }} style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['6'], padding: layers.ref.spacing['6'], border: "1px solid layers.sys.colors.outline", transition: "color 300ms"}}>
                                            <span style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant/50 }} title="Trascina per riordinare">drag_indicator</span>
                                            
                                            <div style={{ flexGrow: "1", display: "flex", flexDirection: "column" }}>
                                                <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8'], marginBottom: layers.ref.spacing['4']}}>
                                                    <span style={{ backgroundColor: sys.colors.primary/20 }} style={{fontWeight: "bold", color: "layers.sys.colors.primary", paddingLeft: layers.ref.spacing['4'], paddingRight: layers.ref.spacing['4'], borderRadius: ref.spacing[9999]}}>
                                                        UDA {idx + 1}
                                                    </span>
                                                    <p style={{ color: sys.colors.[var(--md-sys-color-on-surface)] }} style={{ fontWeight: "bold" }}>{uda.title}</p>
                                                </div>
                                                <p style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", opacity: "0.8" }}>{uda.topic || uda.title}</p>
                                            </div>

                                            <div style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-low)]/50, borderRadius: ref.shape[] }} style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8'], paddingLeft: layers.ref.spacing['4'], paddingRight: layers.ref.spacing['4'], border: "1px solid layers.sys.colors.outline"}}>
                                                <input 
                                                    type="number" 
                                                    value={uda.hours} 
                                                    onChange={e => updateUdaHours(uda.id, parseInt(e.target.value))} 
                                                    style={{ padding: ref.spacing[0] }} style={{ width: "2.5rem", textAlign: "center", backgroundColor: "transparent", fontWeight: "bold", border: "none" }} 
                                                    title="Modifica ore stimate"
                                                />
                                                <span style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }}>ore</span>
                                            </div>

                                            <button onClick={() => removeUdaFromPlan(idx)}  style={{color: "layers.sys.colors.error"}} title="Rimuovi UDA" aria-label="Rimuovi questa UDA dal piano">
                                                <span style={{
  fontFamily: 'Material Symbols Outlined'
}} aria-hidden="true">delete</span>
                                            </button>
                                        </div>
                                    ))}
                                    {plannedUdas.length === 0 && (
                                        <div style={{ padding: ref.spacing[12], backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/20, borderRadius: ref.shape[] }} style={{textAlign: "center", border: "1px solid layers.sys.colors.outline"}}>
                                            <span style={{ color: sys.colors.4xl, color: sys.colors.[var(--md-sys-color-on-surface)]-variant/30 }} style={{marginBottom: layers.ref.spacing['8']}}>calendar_today</span>
                                            <p style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }}>Nessuna UDA pianificata. Aggiungine una o genera dalla KB.</p>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    )}

                    {step === 'preview' && (
                        <div  style={{gap: layers.ref.spacing['6']}}>
                            <SectionHeader 
                                title="5. Anteprima Temporale" 
                                subtitle="Verifica la distribuzione delle UDA nel calendario scolastico."
                                icon="event_repeat"
                            />
                            
                            <InfoCard style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/40 }}>
                                <div >
                                    <div><label >Fine 1° Periodo</label><input type="date" value={term1End} onChange={e => setTerm1End(e.target.value)}  style={{ width: "100%" }} /></div>
                                    <div><label >Termine Lezioni</label><input type="date" value={term2End} onChange={e => setTerm2End(e.target.value)}  style={{ width: "100%" }} /></div>
                                </div>
                            </InfoCard>

                            <div  style={{gap: layers.ref.spacing['8'], paddingTop: layers.ref.spacing['4'], paddingBottom: layers.ref.spacing['4'], overflowY: "auto", paddingRight: layers.ref.spacing['4']}}>
                                {schedulePreview.map((item, idx) => (
                                    <div key={idx} >
                                        <div className={`absolute -left-[11px] top-1 w-5 h-5 rounded-full border-4 border-surface-container-low shadow-sm ${item.end > term2End ? 'bg-error' : 'bg-primary'}`}></div>
                                        <div style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-high)]/30, borderRadius: ref.shape[] }} style={{padding: layers.ref.spacing['8'], border: "1px solid layers.sys.colors.outline"}}>
                                            <p  style={{fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.1em", color: "layers.sys.colors.primary", marginBottom: layers.ref.spacing['4']}}>
                                                {new Date(item.start).toLocaleDateString('it-IT', { day: 'numeric', month: 'short' })} - {new Date(item.end).toLocaleDateString('it-IT', { day: 'numeric', month: 'short' })}
                                            </p>
                                            <h4  style={{marginBottom: layers.ref.spacing['4']}}>{item.uda.title}</h4>
                                            <div style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }} style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}}>
                                                <span  style={{ fontSize: "0.875rem" }}>schedule</span>
                                                <span >{item.uda.hours} ore stimate</span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {step === 'document' && (
                        <div  style={{gap: layers.ref.spacing['8'], display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center"}}>
                            <div style={{ backgroundColor: sys.colors.primary/10 }} style={{width: ref.spacing[96], height: ref.spacing[96], borderRadius: ref.spacing[9999], color: "layers.sys.colors.primary", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: layers.ref.spacing['8']}}>
                                <span style={{ color: sys.colors.6xl }}>task_alt</span>
                            </div>
                            <div>
                                <h3 style={{ color: sys.colors.[var(--md-sys-typescale-headline-small)] }} style={{marginBottom: layers.ref.spacing['8']}}>Pianificazione Completata!</h3>
                                <p style={{ color: sys.colors.[var(--md-sys-color-on-surface)]-variant }} style={{ marginLeft: "auto", marginRight: "auto" }}>
                                    Tutte le UDA e le lezioni sono state salvate. Ora puoi generare il documento di programmazione annuale completo.
                                </p>
                            </div>
                            <M3Button onClick={handleGenerateDoc} disabled={isProcessing} variant="filled" style={{ borderRadius: ref.shape[] }} style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['6']}} title="Scarica il documento finale">
                                {isProcessing ? <AiThinkingGem size="small" inline text="Generazione..." /> : (
                                    <>
                                        <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>description</span>
                                        Genera Documento Word
                                    </>
                                )}
                            </M3Button>
                        </div>
                    )}
                </div>
            </M3DialogContent>

            <M3DialogActions style={{ backgroundColor: sys.colors.[var(--md-sys-color-surface-container-low)]/80 }} style={{borderTop: "1px solid layers.sys.colors.outline"}}>
                    {step !== 'document' && (
                        <>
                            {step !== 'context' && <M3Button onClick={() => setStep(p => p === 'situation' ? 'context' : p === 'methodology' ? 'situation' : p === 'sequence' ? 'methodology' : 'sequence')} variant="text" title="Torna indietro">Indietro</M3Button>}
                            <div style={{ flexGrow: "1" }}></div>
                            {step === 'context' && <M3Button onClick={() => setStep('situation')} variant="filled" title="Vai all'analisi">Avanti</M3Button>}
                            {step === 'situation' && <M3Button onClick={() => setStep('methodology')} variant="filled" title="Vai alla metodologia">Avanti</M3Button>}
                            {step === 'methodology' && <M3Button onClick={() => setStep('sequence')} variant="filled" title="Vai al piano">Avanti</M3Button>}
                            {step === 'sequence' && <M3Button onClick={() => { calculateSchedule(); setStep('preview'); }} disabled={plannedUdas.length === 0} variant="filled" title="Calcola date">Calcola</M3Button>}
                            {step === 'preview' && <M3Button onClick={handleFinalize} disabled={isProcessing} variant="filled" style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}} title="Salva tutto nel database">{isProcessing ? <AiThinkingGem size="small" inline /> : 'Conferma e Salva'}</M3Button>}
                        </>
                    )}
                    {step === 'document' && <M3Button onClick={onClose} variant="text" title="Chiudi wizard">Chiudi</M3Button>}
            </M3DialogActions>
        </M3Dialog>
    );
};

export default AnnualPlanningWizard;

// LEGACY - MD3 Non-compliant

import React, { useState, useMemo } from 'react';
import { View, Valutazione } from '../types';
import { calculatePerformance } from '../utils/evaluationUtils';
import { generateCouncilDataPdf } from '../utils/documentUtils';
import { saveAs } from '../utils/documentUtils';
import { M3Dialog, M3DialogContent, M3DialogActions, M3Button, SectionHeader, TabGroup, M3ExpressiveCard } from './ui';
import { useStudentStore } from '../stores/useStudentStore';
import { useSettingsStore } from '../stores/useSettingsStore';
import { useTheme } from '../theme/theme';

interface ClassSelectionProps {
    onSelectClass: (className: string) => void;
    onNavigate: (view: View) => void;
}

const ClassSelection: React.FC<ClassSelectionProps> = ({ onSelectClass, onNavigate }) => {
  const { layers } = useTheme();
    const students = useStudentStore(state => state.students);
    const evaluations = useStudentStore(state => state.evaluations);
    const competencyEvaluations = useStudentStore(state => state.competencyEvals);
    const settings = useSettingsStore(state => state.settings);
    const userClasses = settings.classi || [];

    const [isPrintCenterOpen, setIsPrintCenterOpen] = useState(false);

    // --- LOGIC: Upcoming Tests (Cross-Class) ---
    const upcomingTests = useMemo(() => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        return evaluations
            .filter(e => {
                const evalDate = new Date(e.data);
                return evalDate >= today;
            })
            .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime())
            .reduce((acc, curr) => {
                const key = `${String(curr.data)}-${String(curr.materia)}-${String(curr.tipo)}`;
                if (!acc.some(i => `${String(i.data)}-${String(i.materia)}-${String(i.tipo)}` === key)) {
                    const student = students.find(s => s.id === curr.studenteId);
                    if (student) {
                        acc.push({ ...curr, className: student.classe });
                    }
                }
                return acc;
            }, [] as (Valutazione & { className: string })[])
            .slice(0, 3); // Take top 3
    }, [evaluations, students]);

    return (
        <div >
             {/* Header Section */}
            <div >
                <div >
                    <h1 st
                    <p style={{ color:  layers.sys.color.onSurfaceVariant }}>Gestione studenti e analisi.</p>
                </div>
            </div>

            {/* --- GLOBAL AGENDA WIDGET --- */}
            {upcomingTests.length > 0 && (
                <section >
                    <h2 st
                        In Arrivo (Tutte le classi)
                    </h2>
                    <div >
                        {upcomingTests.map((test, idx) => (
                            <div key={idx} >
                                <div>
                                    <span >{new Date(test.data).toLocaleDateString('it-IT', { weekday: 'short', day: 'numeric', month: 'short' })}</span>
                                    <h4 >{test.materia}</h4>
                                    <p  style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{test.argomento || test.tipo}</p>
                                </div>
                                <div >{test.className}</div>
                            </div>
                        ))}
                    </div>
                </section>
            )}

            {/* Section 1: Classes Grid (New Widget Style) */}
            <section>
                 <SectionHeader 
                    title="Classi Attive" 
                    icon="school"
                />
                
                {userClasses.length > 0 ? (
                    <div >
                        {userClasses.map((className) => {
                            const classStudents = students.filter(s => s.classe === className);
                            const studentCount = classStudents.length;
                            const studentAverages = classStudents.map(s => {
                                const sEvals = evaluations.filter(e => e.studenteId === s.id);
                                const { grade } = calculatePerformance(s.id, 'Complessivo', sEvals);
                                const numGrade = grade ? parseFloat(grade) : null;
                                return numGrade;
                            }).filter((v): v is number => v !== null);
                            const classAverage = studentAverages.length > 0 
                                ? (studentAverages.reduce((a, b) => a + b, 0) / studentAverages.length).toFixed(1)
                                : '-';
                            return (
                                <M3ExpressiveCard
                                    key={className}
                                    icon="groups"
                                    title={className}
                                    description={`${studentCount} studenti | Media: ${classAverage}`}
                                    color="primary"
                                    onClick={() => onSelectClass(className)}
                                />
                            );
                        })}
                    </div>
                ) : (
                    <div style={{ padding: layers.ref.spacing['8'], backgroundColor: 'layers.sys.color.surfaceContainerLow', borderRadius: layers.ref.shape.corner.large, textAlign: "center", border: "1px solid layers.sys.color.outline" }}>
                        <span style={{ color: 'layers.sys.color.onSurfaceVariant', opacity: 0.5, marginBottom: layers.ref.spacing['8'] }}>domain_disabled</span>
                        <p style={{ color: 'layers.sys.color.onSurfaceVariant' }}>Nessuna classe definita</p>
                        <p style={{ color: 'layers.sys.color.onSurfaceVariant', marginTop: layers.ref.spacing['4'], marginBottom: layers.ref.spacing['6'] }}>
                            Vai nelle impostazioni per configurare le tue classi e iniziare.
                        </p>
                        <M3Button onClick={() => onNavigate('settings')} variant="filled">
                            Vai a Impostazioni
                        </M3Button>
                    </div>
                )}
            </section>

            {/* Section 2: Global Tools */}
            <section>
                 <SectionHeader 
                    title="Gestione Rapida" 
                    icon="settings_applications"
                />
                
                <div >
                    <button 
                        onClick={() => onNavigate('studenti')} 
                        
                    >
                        <span >group_add</span>
                        <span >Importazione Massiva</span>
                        <span >Carica studenti da CSV</span>
                    </button>

                    <button 
                        onClick={() => setIsPrintCenterOpen(true)} 
                        
                    >
                        <span >print</span>
                        <span >Centro Stampe</span>
                        <span >Report PDF multi-classe</span>
                    </button>

                    <button 
                        onClick={() => onNavigate('analytics')} 
                        
                    >
                        <span >analytics</span>
                        <span >Analytics Hub</span>
                        <span >Dashboard dati avanzata</span>
                    </button>

                    <button 
                        onClick={() => onNavigate('didattica-inclusiva')} 
                        
                    >
                        <span  style={{color: "layers.sys.color.tertiary"}}>accessibility_new</span>
                        <span >Didattica Inclusiva</span>
                        <span >Gestione PEI/PDP globale</span>
                    </button>
                </div>
            </section>

            {/* INTERNAL MODAL: PRINT CENTER */}
            {isPrintCenterOpen && (
                <PrintCenterModal 
                    userClasses={userClasses}
                    onClose={() => setIsPrintCenterOpen(false)}
                    students={students}
                    evaluations={evaluations}
                    competencyEvaluations={competencyEvaluations}
                    settings={settings}
                />
            )}
        </div>
    );
};

// --- Sub-component: Print Center Modal ---
const PrintCenterModal: React.FC<{ 
    userClasses: string[]; 
    onClose: () => void;
    students: Studente[];
    evaluations: Valutazione[];
    competencyEvaluations: ValutazioneCompetenza[];
    settings: TimetableSettings;
}> = ({ userClasses, onClose, students, evaluations, competencyEvaluations, settings }) => {
    const [selectedClasses, setSelectedClasses] = useState<string[]>([]);
    const [periodo, setPeriodo] = useState<PeriodoValutazione>('primo-quadrimestre');
    const [isProcessing, setIsProcessing] = useState(false);

    const toggleClass = (c: string) => {
        setSelectedClasses(prev => prev.includes(c) ? prev.filter(k => k !== c) : [...prev, c]);
    };

    const handlePrintAll = async () => {
        if (selectedClasses.length === 0) return;
        setIsProcessing(true);
        try {
            for (const className of selectedClasses) {
                const classStudents = students.filter(s => s.classe === className);
                const blob = await generateCouncilDataPdf(
                    className,
                    periodo,
                    classStudents,
                    evaluations,
                    competencyEvaluations,
                    settings
                );
                // FIX DEFINITIVO: String() per il periodo nel nome file
                saveAs(blob, `Report_Consiglio_${String(className)}_${String(periodo)}.pdf`);
                // Small delay to allow download initiation
                await new Promise(r => setTimeout(r, 800));
            }
        } catch(e) {
            console.error(e);
        } finally {
            setIsProcessing(false);
            onClose();
        }
    };

    return (
        <M3Dialog
            title="Centro Stampe"
            onClose={onClose}
            maxWidth="md"
        >
            <M3DialogContent style={{gap: layers.ref.spacing['6']}}>
                    <p style={{ color:  layers.sys.color.onSurfaceVariant }}>Seleziona le classi e il periodo per cui generare il prospetto voti (PDF).</p>
                    
                    <div style={{gap: layers.ref.spacing['2']}}>
                        <label st
                        <TabGroup
                            tabs={[
                                { id: 'primo-quadrimestre', label: '1Q' },
                                { id: 'secondo-quadrimestre', label: 'Finale' }
                            ]}
                            activeTab={periodo}
                            onTabChange={(id) => setPeriodo(id as PeriodoValutazione)}
                        />
                    </div>

                    <div style={{gap: layers.ref.spacing['2']}}>
                        <label st
                        <div style={{display: "flex", flexWrap: "wrap", gap: layers.ref.spacing['8']}}>
                            {userClasses.map(c => (
                                <div 
                                    key={c} 
                                    onClick={() => toggleClass(c)}
                                    className={`px-4 py-4 rounded-full border cursor-pointer transition-all flex items-center gap-8 ${
                                        selectedClasses.includes(c) 
                                            ? 'bg-primary text-on-primary border-primary' 
                                            : 'bg-[var(--md-sys-color-surfaceContainerLow)] text-[var(--md-sys-color-onSurface)]-variant border-[var(--md-sys-color-outline-variant)] hover:bg-[var(--md-sys-color-surfaceContainerHigh)]'
                                    }`}
                                >
                                    {selectedClasses.includes(c) && <span  style={{ fontSize: "1.125rem" }}>check</span>}
                                    Classe {c}
                                </div>
                            ))}
                        </div>
