    alignItems: 'center',

    // Desktop overrides
    ...(isMobile ? {} : {
      flexDirection: 'column',
      gap: 'var(--md-sys-spacing-2)', // 8px gap
      paddingTop: 'var(--md-sys-spacing-4)', // 16px
      paddingBottom: 'var(--md-sys-spacing-4)', // 16px
      justifyContent: 'flex-start',
    })
  };

  return (
    <>
      <style>
        {`
          @keyframes badge-appear {
            from {
              transform: scale(0);
              opacity: 0;
            }
            to {
              transform: scale(1);
              opacity: 1;
            }
          }
        `}
      </style>
      <nav
        style={containerStyle}
        role="navigation"
        aria-label="Navigazione principale"
      >
      <div style={itemsContainerStyle}>
        {items.map((item) => {
          const isActive = isItemActive(item, activeView);

          const itemStyle: React.CSSProperties = {
            // Reset button styles
            backgroundColor: 'transparent',
            border: 'none',
            cursor: 'pointer',
            outline: 'none',

            // Layout
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 'var(--md-sys-spacing-1)', // 4px gap between icon and label

            // Size
            width: 'var(--md-sys-spacing-14)', // 56px
            minHeight: 'var(--md-sys-spacing-14)', // 56px
            padding: 'var(--md-sys-spacing-2) 0', // 8px top/bottom

            // Shape
            borderRadius: 'var(--md-sys-shape-corner-medium)', // 12px

            // State colors - default
            color: 'var(--md-sys-color-onSurface-variant)',

            // Transition
            transition: 'all var(--md-sys-motion-duration-short2) var(--md-sys-motion-easing-standard)',

            // Remove tap highlight on mobile
            WebkitTapHighlightColor: 'transparent',

            // Active state
            ...(isActive && {
              backgroundColor: 'var(--md-sys-color-primaryContainer)',
              color: 'var(--md-sys-color-on-primaryContainer)',
              boxShadow: 'var(--md-sys-elevation-level1)',
            })
          };

          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id, null)}
              style={itemStyle}
              onMouseEnter={(e) => {
                if (!isActive) {
                  e.currentTarget// removed runtime mutation
                }
              }}
              onMouseLeave={(e) => {
                if (!isActive) {
                  e.currentTarget// removed runtime mutation
                }
              }}
              onFocus={(e) => {
                e.currentTarget// removed runtime mutation
                e.currentTarget// removed runtime mutation
              }}
              onBlur={(e) => {
                e.currentTarget// removed runtime mutation
                e.currentTarget// removed runtime mutation
              }}
              aria-label={item.label}
              aria-current={isActive ? 'page' : undefined}
            >
              {/* Icon Container */}
              <div
                style={{position: 'relative',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: layers.ref.spacing['8'], // 32px
                  height: layers.ref.spacing['8'], // 32px
                  borderRadius: 'layers.ref.shape.corner.full', // 50%
                  transition: `all ${layers.motion.duration.short2} ${layers.motion.easing.standard}`}}
              >
                <span
