                                        </M3Button>
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );

    return (
        <div >
            <div  style={{display: "flex", flexDirection: "column", justifyContent: "space-between", gap: layers.ref.spacing['8']}}>
                <SectionHeader 
                    title="Orientamento & E-Portfolio"
                    subtitle="Monitoraggio delle 30 ore annuali e gestione documenti istituzionali (Linee Guida 2023)."
                     style={{ flexGrow: "1" }}
                />
                <div >
                    <SelectField 
                        label="Classe"
                        value={selectedClass}
                        onChange={e => setSelectedClass(e.target.value)}
                    >
                        {userClasses.map(c => (
                            <option key={c} value={c}>Classe {c}</option>
                        ))}
                    </SelectField>
                </div>
            </div>

            <div style={{display: "grid", gridTemplateColumns: "1fr", gap: layers.ref.spacing['8']}}>
                <InfoCard 
                    title="Ore Medie Classe" 
                    description="Target Ministeriale: 30h"
                    icon="schedule"
                    variant="primary"
                >
                    <div style={{marginTop: layers.ref.spacing['4']}}>
                        <span style={{fontWeight: "900", color: layers.sys.color.primary}}>{totalHours}h</span>
                        <p style={{ color: layers.sys.color.onSurfaceVariant, marginTop: layers.ref.spacing['4'] }}>
                            {totalHours >= 30 ? '✅ Target raggiunto per la classe' : `Mancano ${30 - totalHours}h al target`}
                        </p>
                    </div>
                </InfoCard>

                <InfoCard 
                    title="Completamento E-Portfolio" 
                    description="Studenti con Capolavoro"
                    icon="auto_awesome"
                    variant="tertiary"
                >
                    <div style={{marginTop: layers.ref.spacing['4']}}>
                        <span style={{fontWeight: "900", color: layers.sys.color.tertiary}}>
                            {filteredStudents.filter(s => studentStates[s.id]?.hasCapolavoro).length}/{filteredStudents.length}
                        </span>
                    </div>
                </InfoCard>

                <InfoCard 
                    title="Autovalutazioni" 
                    description="Riflessioni caricate"
                    icon="psychology"
                    variant="secondary"
                >
                    <div style={{marginTop: layers.ref.spacing['4']}}>
                        <span style={{fontWeight: "900", color: layers.sys.color.secondary}}>
                            {filteredStudents.filter(s => studentStates[s.id]?.hasAutovalutazione).length}/{filteredStudents.length}
                        </span>
                    </div>
                </InfoCard>
            </div>

            <div style={{ borderRadius: ref.shape[25] }} style={{border: "1px solid layers.sys.color.outline"}}>
                <div style={{ backgroundColor: sys.colors.surface/30 }} style={{display: "flex", borderBottom: "1px solid layers.sys.color.outline", padding: layers.ref.spacing['8']}}>
                    <button 
                        onClick={() => setActiveTab('activities')}
                        className={`flex-grow py-4 font-black text-[10px] uppercase tracking-widest transition-all rounded-[var(--md-sys-shape-corner-large)] ${activeTab === 'activities' ? 'bg-primary text-on-primary shadow-[var(--md-sys-elevation-level2)]' : 'text-[var(--md-sys-color-onSurface)]-variant hover:bg-[var(--md-sys-color-surfaceContainerHigh)]'}`}
                    >
                        Attivit� di Orientamento
                    </button>
                    <button 
                        onClick={() => setActiveTab('students')}
                        className={`flex-grow py-4 font-black text-[10px] uppercase tracking-widest transition-all rounded-[var(--md-sys-shape-corner-large)] ${activeTab === 'students' ? 'bg-primary text-on-primary shadow-[var(--md-sys-elevation-level2)]' : 'text-[var(--md-sys-color-onSurface)]-variant hover:bg-[var(--md-sys-color-surfaceContainerHigh)]'}`}
                    >
                        Stato Studenti
                    </button>
                </div>

                <div style={{padding: layers.ref.spacing['6']}}>
                    {activeTab === 'activities' ? renderActivitiesTab() : renderStudentsTab()}
                </div>
            </div>

            {/* Modals */}
            <AddOrientamentoActivityModal
                isOpen={isAddActivityModalOpen}
                onClose={() => setIsAddActivityModalOpen(false)}
                onSave={(a) => {
                    onSaveActivity(a);
                    showToast('Attività salvata con successo', 'success');
                }}
                userClasses={userClasses}
            />

            {viewingStudent && (
                <StudentEPortfolioModal
                    isOpen={!!viewingStudent}
                    onClose={() => setViewingStudent(null)}
                    student={viewingStudent}
                    state={studentStates[viewingStudent.id] || { studentId: viewingStudent.id, hasCapolavoro: false, hasAutovalutazione: false, totalHours: 0, activities: [], ePortfolio: [], selfReflection: ', tutorNotes: ' }}
                    entries={ePortfolioEntries.filter(e => e.studentId === viewingStudent.id)}
                    onUpdateState={onUpdateStudentState}
                    onAddEntry={(e) => {
                        onSaveEPortfolio(e);
                        showToast('Documento aggiunto all\'E-Portfolio', 'success');
                    }}
                />
            )}
        </div>
    );
};

