                                 <div style={{gap: layers.ref.spacing['1']}}>
                                    <p style={{fontWeight: "900", textTransform: "uppercase", color: "layers.sys.color.primary", letterSpacing: "0.1em", opacity: "0.7"}}>Classe Selezionata</p>
