                                break;
                            case 'evaluations':
                                componentProps = { students, evaluations, setEvaluations, competencyEvaluations: competencyEvals, setCompetencyEvaluations: setCompetencyEvals, userClasses: settings.classi, settings, aiSettings, initialClass: typeof viewContext === 'string' ? viewContext : undefined, onClearInitialStudent: () => setViewContext({ initialStudentId: undefined }), onOpenInclusionPlanEditor: (student: Studente) => handleNavigate('didattica-inclusiva', { student }), showGuidanceTips: settings.showGuidanceTips, register: finalizedRegister, lessons };
                                break;
                            case 'register':
                                componentProps = { entries: finalizedRegister, lessons, students, initialClass: typeof viewContext === 'string' ? viewContext : undefined };
                                break;
                            case 'improvement-guide':
                                componentProps = { selectedClass: typeof viewContext === 'string' ? viewContext : '', students, evaluations, competencyEvaluations: competencyEvals, lessons, register: finalizedRegister, settings, aiSettings };
                                break;
                            case 'consiglio-di-classe':
                                componentProps = { selectedClass: typeof viewContext === 'string' ? viewContext : '', students, evaluations, giudizi, onSaveGiudizio: actions.saveGiudizio, settings, aiSettings, annoScolasticoCorrente: settings.annoScolasticoCorrente, onViewStudentProfile: setStudentProfileContext, competencyEvaluations: competencyEvals };
                                break;
                            case 'class-competency-dashboard':
                                componentProps = { selectedClass: typeof viewContext === 'string' ? viewContext : '', students, competencyEvaluations: competencyEvals, settings, onViewStudentProfile: setStudentProfileContext };
                                break;
                            case 'analytics':
                                componentProps = { userClasses: settings.classi, students, evaluations, competencyEvaluations: competencyEvals, settings, aiSettings };
                                break;
                            case 'student-dashboard':
                                componentProps = { students, onLogin: (student: Studente) => handleNavigate('student-workspace', { studentId: student.id }), onCancel: () => handleNavigate('home'), securityPin: safeSecurityPin };
                                break;
                            case 'teacher-inbox':
                                componentProps = { submissions: safeSubmissions, students, lessons, onGradeSubmission: handleGradeSubmission, onClose: () => handleBack(true) };
                                break;
                            case 'competency-levels':
                                componentProps = { competenze: settings.competenze };
                                break;
                            case 'curriculum-manager':
                                componentProps = { curricula: curricula || [], onUpdateCurricula: setCurricula, settings, aiSettings, onNavigate: handleNavigate };
                                break;
                            case 'live-assistant':
                                componentProps = { students, evaluations, slots, lessons, pianiInclusione, knowledgeBase, onNavigate: handleNavigate, onCreateEvent: (eventWithoutId: Record<string, unknown>) => { const newEvent = { ...eventWithoutId, id: `evt-${Date.now()}-${Math.random()}` }; setEventi((prev: Record<string, unknown>[]) => [...prev, newEvent]); }, onScheduleLesson: (data: Record<string, unknown>) => { onScheduleLesson(data); modals.setIsLiveAssistantModalOpen?.(false); }, onAddEvaluation: (data: Record<string, unknown>) => { handleAddEvaluation(data); modals.setIsLiveAssistantModalOpen?.(false); }, onCreateUda: (data: Record<string, unknown>) => { handleCreateUda(data); modals.setIsLiveAssistantModalOpen?.(false); }, onAddNote: (data: Record<string, unknown>) => { handleAddNote(data); modals.setIsLiveAssistantModalOpen?.(false); }, onMarkAttendance: (data: Record<string, unknown>) => { onMarkAttendance(data); modals.setIsLiveAssistantModalOpen?.(false); }, onLoadDemoData: () => { handleLoadDemoData(); modals.setIsLiveAssistantModalOpen?.(false); }, userContext: user };
                                break;
                            case 'teacher-presentation-view':
                                componentProps = { onNavigate: handleNavigate };
                                break;
                        }

                        return config.auraWrapper !== false ? (
                            <AuraView {...wrapperProps}>
                                <Component {...componentProps} />
                            </AuraView>
                        ) : (
                            <div className={config.fullWidth ? 'w-full' : 'max-w-7xl mx-auto px-4'}>
                                <Component {...componentProps} />
                            </div>
                        );
                    }

                    // 404 Fallback
                    return (
                        <AuraView>
                            <div style={{ padding: layers.ref.spacing['4'], textAlign: "center", opacity: "0.5" }}>
                                <h2 >Vista "{view}" non trovata</h2>
                                <button onClick={() => actions.handleNavigate('home')}  style={{marginTop: layers.ref.spacing['4']}}>
                                    Torna alla Home
                                </button>
                            </div>
                        </AuraView>
                    );
                })()}
            </Suspense>
        );
    }, [view, viewContext, appState, actions, modals]);

    return (
        <>
            {renderView}
            {modals.isRegisterImportOpen && (
                <RegisterImportDialog 
                    onClose={() => setIsRegisterImportOpen?.(false)}
                    onImport={(result) => {
                        if (result.students.length > 0) {
                            importStudents(result.students);
                        }
                        if (result.evaluations.length > 0) {
                            importEvaluations(result.evaluations);
                        }
                        showToast('Dati importati con successo!', 'success');
                    }}
                />
            )}
        </>
    );
}

export default ViewManager;

// LEGACY - MD3 Non-compliant
// MD3 Pure: Migrated to inline styles using MD3 tokens for voice recorder button states and interactions
// All voice-note-recorder-* classes removed in favor of token-based styling
// Migration Date: Phase 7 (Remaining Components Migration) - useTheme compliance

import React, { useState, useRef, useEffect } from 'react';
import { useTheme } from '../theme/theme';
import { getGoogleAIClient } from '../services/aiClient.ts';
import { useTheme } from '../theme/theme';

interface VoiceNoteRecorderProps {
    onTranscription: (text: string) => void;
    compact?: boolean;
}

const VoiceNoteRecorder: React.FC<VoiceNoteRecorderProps> = ({ onTranscription, compact = false }) => {
  const { layers } = useTheme();
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const theme = useTheme();
    const [isRecording, setIsRecording] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const [audioLevel, setAudioLevel] = useState(0);

    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const animationFrameRef = useRef<number | null>(null);

    const cleanupAudioResources = () => {
        if (animationFrameRef.current) {
            cancelAnimationFrame(animationFrameRef.current);
            animationFrameRef.current = null;
        }

        if (sourceRef.current) {
            sourceRef.current.disconnect();
            sourceRef.current = null;
        }

        if (analyserRef.current) {
            analyserRef.current.disconnect();
            analyserRef.current = null;
        }

        // IMPORTANT: Do NOT close context immediately on stop, only on unmount.
        // Or if we create new one each time, ensure we close old one.
        if (audioContextRef.current) {
            if (audioContextRef.current.state !== 'closed') {
                audioContextRef.current.close();
            }
            audioContextRef.current = null;
        }

        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
    };

    useEffect(() => {
        // Global cleanup ONLY on unmount
        return () => {
            cleanupAudioResources();
        };
    }, []);

    const startRecording = async () => {
        cleanupAudioResources(); // Clean previous session if any

        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            streamRef.current = stream;

            // Use the updated global definition for webkitAudioContext
            const AudioContextClass = window.AudioContext || (window as Window & typeof globalThis & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
            const audioCtx = new AudioContextClass();
            await audioCtx.resume(); // CRITICAL: Ensure context is active (User Interaction policy)

            const analyser = audioCtx.createAnalyser();
            analyser.fftSize = 32;
            const source = audioCtx.createMediaStreamSource(stream);
            source.connect(analyser);
            // DO NOT CONNECT to destination to avoid feedback loop

            audioContextRef.current = audioCtx;
            analyserRef.current = analyser;
            sourceRef.current = source;

            // Recorder
            const mediaRecorder = new MediaRecorder(stream);
            mediaRecorderRef.current = mediaRecorder;
            audioChunksRef.current = [];

            mediaRecorder.ondataavailable = (event) => {
                if (event.data.size > 0) {
                    audioChunksRef.current.push(event.data);
                }
            };

            mediaRecorder.onstop = handleStopRecording;
            mediaRecorder.start();
            setIsRecording(true);
            // Notify global UI that assistant is listening
            try { window.dispatchEvent(new CustomEvent('assistant:recording', { detail: { recording: true } })); } catch { /* ignore */ }
            visualize();

        } catch (error) {
            console.error("Error accessing microphone:", error);
            alert("Impossibile accedere al microfono. Verifica i permessi del browser.");
        }
    };

    const visualize = () => {
        if (!analyserRef.current) return;
        const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
        analyserRef.current.getByteFrequencyData(dataArray);

        // Calculate average volume
        const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
        setAudioLevel(average);

        // Keep loop running if recording OR processing (to finish animation smoothly)
        if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
            animationFrameRef.current = requestAnimationFrame(visualize);
        } else {
            setAudioLevel(0);
        }
    };

    const stopRecording = () => {
        if (mediaRecorderRef.current && isRecording) {
            mediaRecorderRef.current.stop();
            // Don't set isRecording to false here immediately, wait for onstop
            // But we can trigger processing state UI
            setIsProcessing(true);
        }
    };

    const handleStopRecording = async () => {
        setIsRecording(false); // Update UI state
        // Notify global UI that assistant stopped listening
        try { window.dispatchEvent(new CustomEvent('assistant:recording', { detail: { recording: false } })); } catch { /* ignore */ }

        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });

        // Cleanup streams immediately to release mic
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }

        try {
            const reader = new FileReader();
            reader.readAsDataURL(audioBlob);
            reader.onloadend = async () => {
                const base64data = reader.result as string;
                // Check valid data
                if (!base64data || !base64data.includes(',')) {
                    console.warn("Empty audio recording");
                    setIsProcessing(false);
                    return;
                }
                const base64AudioContent = base64data.split(',')[1];

                const ai = await getGoogleAIClient();
                const response = await ai.models.generateContent({
                    model: 'gemini-2.5-flash',
                    contents: {
                        parts: [
                            { inlineData: { mimeType: 'audio/webm', data: base64AudioContent } },
                            { text: "Trascrivi questa nota vocale di un insegnante per il registro di classe. Correggi eventuali errori grammaticali minori, usa la punteggiatura corretta e, se ci sono elenchi, formattali con trattini. Restituisci solo il testo." }
                        ]
                    }
                });

                if (response.text) {
                    onTranscription(response.text.trim());
                }
                setIsProcessing(false);
                cleanupAudioResources(); // Full cleanup
            };
        } catch (error) {
            console.error("Error during transcription:", error);
            alert("Errore durante la trascrizione. Riprova.");
            setIsProcessing(false);
            cleanupAudioResources();
        }
    };

    // Dynamic style for the visualizer ring
    const visualizerStyle = {
        boxShadow: isRecording ? `0 0 0 ${Math.min(audioLevel / 5, 10)}px var(--colors-error-container)` : 'none',
        transform: isRecording ? `scale(${1 + (audioLevel / 255) * 0.2})` : 'scale(1)',
        transition: 'box-shadow var(--motion-duration-short1) var(--motion-easing-standard), transform var(--motion-duration-short1) var(--motion-easing-standard)'
    };

    return (
        <button
            type="button"
            onClick={isRecording ? stopRecording : startRecording}
            disabled={isProcessing}
            style={{display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: compact ? '0' : layers.ref.spacing['2'],
                padding: compact ? layers.ref.spacing['3'] : `${layers.ref.spacing['4']} ${layers.ref.spacing['5']}`,
                borderRadius: layers.ref.shape.corner.large,
                border: 'none',
                backgroundColor: isRecording 
                    ? layers.sys.color.errorContainer 
                    : layers.sys.color.secondaryContainer,
                color: isRecording 
                    ? layers.sys.color.onErrorContainer 
                    : layers.sys.color.onSecondaryContainer,
                fontSize: layers.ref.typography.labelLarge.fontSize,
                fontWeight: layers.ref.typography.labelLarge.fontWeight,
                cursor: isProcessing ? 'not-allowed' : 'pointer',
                opacity: isProcessing ? 0.6 : 1,
                transition: `all ${layers.motion.duration.short} ${layers.motion.easing.standard}`,
                position: 'relative',
                overflow: 'hidden',
                minWidth: compact ? layers.ref.spacing['4'] : 'auto',
