};

const inputErrorStyle: React.CSSProperties = {
  ...inputStyle,
  borderColor: 'var(--md-sys-color-error)',
  boxShadow: '0 0 0 2px var(--md-sys-color-error-container)',
};

const helperStyle: React.CSSProperties = {
  marginTop: 'var(--md-sys-spacing-1)',
